referenceSolutions.javascript:
export function countIslands(grid) {
  const rows = grid.length, columns = grid[0]?.length ?? 0;
  const visited = new Set();
  let islands = 0;
  for (let row = 0; row < rows; row++) {
    for (let column = 0; column < columns; column++) {
      const start = row * columns + column;
      if (grid[row][column] !== 1 || visited.has(start)) continue;
      islands++;
      visited.add(start);
      const stack = [start];
      while (stack.length) {
        const cell = stack.pop();
        const r = Math.floor(cell / columns), c = cell % columns;
        for (const [nr, nc] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
          const key = nr * columns + nc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < columns && grid[nr][nc] === 1 && !visited.has(key)) {
            visited.add(key);
            stack.push(key);
          }
        }
      }
    }
  }
  return islands;
}

